<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import helperMixin from 'src/mixins/helperMixin';
import { useMasterDataLookupStore, useUserStore } from 'src/store/main';
import xmlTablePath from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/xmlTablePath.vue';
import xmlTableCreation from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/xmlTableCreation.vue';
export default {
  mixins: [helperMixin],
  name: 'CustomPreset',
  components: {
    xmlTablePath,
    xmlTableCreation,
  },
  data() {
    return {
      api_tabs: 'params',
      fields_read_only: false,
      preset_api: '',
      selected_ion: false,
      creation_step: 0,
      auth_json_file: null,

      // Your data properties go here
    };
  },
  methods: {
    addColumnToTable() {
      if (this.column_paths.length === 0) {
        if (this.preset_information['column_name'].toLowerCase() != 'id') {
          notify.error(
            this.$t('column_id_required'),
          );
          return;
        }
      }
      this.column_paths.push({
        key: this.preset_information['column_name'],
        value: this.preset_information['column_value_name'],
      });
      this.preset_information['column_name'] = '';
      this.preset_information['column_value_name'] = '';
      this.testDataExtraction('template');
    },
    removeColumnFromTable(index) {
      this.column_paths.splice(index, 1);
    },
    addBodyToTable() {
      this.preset_body.push({
        key: this.preset_information['query_body_key'],
        value: this.preset_information['query_body_value'],
      });
      this.preset_information['query_body_key'] = '';
      this.preset_information['query_body_value'] = '';
    },
    removeBodyFromTable(index) {
      this.preset_body.splice(index, 1);
    },
    addHeaderToTable() {
      this.preset_headers.push({
        key: this.preset_information['query_header_key'],
        value: this.preset_information['query_header_value'],
      });
      this.preset_information['query_header_key'] = '';
      this.preset_information['query_header_value'] = '';
    },
    removeHeaderFromTable(index) {
      this.preset_headers.splice(index, 1);
    },
    addParamToTable() {
      this.preset_parameters.push({
        key: this.preset_information['query_param_key'],
        value: this.preset_information['query_param_value'],
      });
      this.preset_information['query_param_key'] = '';
      this.preset_information['query_param_value'] = '';
    },
    removeParamFromTable(index) {
      this.preset_parameters.splice(index, 1);
    },
    checkInputs() {
      if (!this.preset_information['url_user_input']) {
        return false;
      }
      if (!this.preset_information['data_type']) {
        return false;
      }

      if (this.preset_information['data_type'].includes(' ')) {
        return false;
      }

      return true;
    },
    async continueStepper() {
      if (this.creation_step === 2) {
        const valid = this.checkInputs();
        if (!valid) {
          notify.error(this.$t('fill_all_fields'));
          return;
        }
        await this.testEndpointResponse('template')
          .then((response) => {
            if (response.success) {
              (this.$refs.stepper as any)?.next?.();
              return;
            }
          })
          .catch((error: any) => {
            return;
          });
      }
      if (this.creation_step === 4) {
        if (this.column_paths.length === 0) {
          notify.error(
            this.$t('column_required'),
          );
          return;
        }
        await this.createMasterData('template', 'create')
          .then((response) => {
            this.loading = true;
            notify.success(
              this.$t('custom_master_data_template_created'),
            );
            this.$router.push('/settings/master-data');
          })
          .catch((error: any) => {
            logError(error);
          });
      }
      (this.$refs.stepper as any)?.next?.();
    },
    checkFileType(files) {
      // file.type === 'application/json' ||
      // logInfo('FILES', files)
       
      return files.filter(
        (file) => file.name.endsWith('.ionapi') || file.name.endsWith('.json'),
      );
    },
    handleUploadJson() {
      if (this.auth_json_file) {
        const reader = new FileReader();
        reader.onload = (e: any) => {
          this.preset_information['auth_json'] = e.target.result;
        };
        reader.readAsText(this.auth_json_file);
      }
    },
    handleUploadIonJson() {
      if (this.auth_json_file) {
        const reader = new FileReader();
        reader.onload = (e: any) => {
          const json_file = JSON.parse(e.target.result);
          this.preset_information['auth_json'] = e.target.result;
          this.preset_information['url'] =
            json_file['iu'] + '/' + json_file['ti'];
        };
        reader.readAsText(this.auth_json_file);
      }
      this.preset_information['auth_type'] = {
        label: 'ION API',
        value: 'ionapi',
      };
      this.preset_information['body_type'] = {
        label: 'application/json',
        value: 'application/json',
      };
      this.fields_read_only = true;
      (this.$refs.stepper as any)?.next?.();
    },
    onRejected() {
      notify.error(
        this.$t('only_json_files_allowed'),
      );
    },
    // Your methods go here
  },
  setup() {
    const master_data_store = useMasterDataLookupStore();
    const {
      preset_parameters,
      preset_headers,
      preset_body,
      data_mode,
      column_paths,
      auth_options,
      preset_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,
      loading,
    } = storeToRefs(master_data_store);
    const {
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
    } = master_data_store;

    const user_store = useUserStore();
    const { sub_org_id } = storeToRefs(user_store);
    return {
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,

      loading,
      data_mode,
      sub_org_id,
      preset_parameters,
      preset_headers,
      preset_body,
      column_paths,
      auth_options,
      preset_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,
    };
  },
  mounted() {
    // Code to run when the component is mounted
  },
};
</script>

